                    r".*vision_tower",
                    r".*multi_modal_projector",
                    "self_attn.compressor.kv_proj",
                    "self_attn.compressor.gate_proj",
                    "self_attn.indexer.k_proj",
                    "self_attn.indexer.weights_proj",
